(() => {
  if(new URLSearchParams(location.search).get('id') !== 'medscan') return;
  const project = window.portfolioData.projects.find(item => item.id === 'medscan');
  document.title = 'MedScan — Bernardo Henrique';
  document.documentElement.lang = 'pt-BR';
  const labels = document.querySelectorAll('.project-labels span');
  labels[0].textContent = 'Saúde digital';
  labels[1].textContent = 'MEDTECH';
  document.querySelector('h1').textContent = project.title;
  document.querySelector('.project-title-line > span').textContent = '/ Projeto real';
  document.querySelector('.project-summary-text').textContent = project.summary;
  const meta = document.querySelectorAll('.project-meta > div');
  meta[0].querySelector('dt').textContent = 'Atuação';
  meta[0].querySelector('dd').textContent = 'Desenvolvimento e integração';
  meta[1].querySelector('dt').textContent = 'Equipe';
  meta[1].querySelector('dd').textContent = 'MEDTECH · FUNEC Riacho';
  meta[2].querySelector('dt').textContent = 'Tecnologias';
  const tools = document.querySelector('.tool-list');
  tools.replaceChildren();
  [['React Native','react'],['Node.js','nodejs'],['MongoDB','mongodb']].forEach(([name, icon]) => {
    const tile = document.createElement('span');
    tile.className = 'tool';
    tile.title = name;
    const img = document.createElement('img');
    img.src = 'assets/technologies/' + icon + '.svg';
    img.alt = name;
    img.width = 22; img.height = 22;
    tile.append(img); tools.append(tile);
  });
  const oldButton = document.querySelector('.project-actions button');
  const demo = document.createElement('a');
  demo.className = 'live-preview';
  demo.textContent = 'Abrir demonstração ↗';
  demo.href = project.liveUrl;
  demo.target = '_blank';
  demo.rel = 'noopener noreferrer';
  oldButton.replaceWith(demo);
  document.querySelector('.project-actions a:last-child').textContent = 'Contato';
  const frame = document.querySelector('.project-image-space');
  frame.classList.add('has-image');
  frame.removeAttribute('role');
  frame.removeAttribute('aria-label');
  const img = document.createElement('img');
  img.src = 'assets/medscan-welcome-detail.png';
  img.alt = 'Tela de boas-vindas do MedScan: Sua saúde, em primeiro plano.';
  img.width = 1842; img.height = 1012;
  frame.append(img);
})();
